scripts.build:dts:
cat > dist/index.d.ts << 'EOF'
export enum AuthStatus {
  Unauthenticated = "unauthenticated",
  NeedsTfa = "needs-tfa",
  NeedsPasswordChange = "needs-password-change",
  Authenticated = "authenticated",
  Unknown = "unknown",
  Loading = "loading",
}

interface AuthUserProfile {
  userId: string;
  username: string;
  role: string;
  tfaVerified: boolean;
  firstLogin: boolean;
  tfaEnabled: boolean;
  isActive: boolean;
  lastLoginAt?: Date | null;
  createdAt: Date;
  updatedAt: Date;
}

export interface UseAuthReturn {
  user: AuthUserProfile | null;
  status: AuthStatus;
  login: (credentials: any) => Promise<void>;
  verifyTfa: (code: string) => Promise<void>;
  setPasswordFirstLogin: (passwordsDto: any) => Promise<void>;
  logout: () => Promise<void>;
  isLoading: boolean;
}

export declare const useAuth: () => UseAuthReturn;
EOF
